const unavailable=()=>Promise.reject(new Error('No coordinator authorized'));
export default{fetch(){return new Response(null,{status:404})},async queue(batch,env){const receipts=[];const messages=batch.messages.map(m=>({id:m.id,timestamp:m.timestamp,attempts:m.attempts,body:m.body,ack(){receipts.push({id:m.body.submissionId,acceptedAt:Date.now(),attempt:m.attempts});m.ack();},retry(options){m.retry(options);}}));await consume({queue:batch.queue,metadata:batch.metadata,messages,ackAll:()=>batch.ackAll(),retryAll:options=>batch.retryAll(options)},withErasureRecovery({...env,STATEMENT_EXTRACTION_WORKFLOW:env.CHILD,USER_TRANSACTION_COORDINATOR:{getByName:()=>({fetch:unavailable})}}));if(receipts.length)await env.DB.batch(receipts.map(r=>env.DB.prepare('INSERT INTO receipts VALUES (?,?,?) ON CONFLICT(id) DO NOTHING').bind(r.id,r.acceptedAt,r.attempt)));}};
